/*
 * Lightweight translation layer.
 * Pages are written in English. For another language, the dictionary
 * assets/i18n/<code>.json (generated by build.py) is fetched once, and every text node
 * plus the placeholder / aria-label / title attributes are looked up by their English
 * text (whitespace collapsed). Missing entries stay in English.
 * To add a language: add it to LANGS below and to the language menu in
 * src/partials/header.html, then add src/i18n/<code>.json and run build.py.
 */
(function () {
  'use strict';

  // code: [short label, text direction, extra Google Font family or '']
  var LANGS = {
    en: ['EN', 'ltr', ''],
    bn: ['বাং', 'ltr', 'Hind+Siliguri:wght@400;500;600;700'],
    ar: ['ع', 'rtl', 'Noto+Sans+Arabic:wght@400;500;600;700'],
    ur: ['اردو', 'rtl', 'Noto+Nastaliq+Urdu:wght@400;600;700'],
    zh: ['中文', 'ltr', 'Noto+Sans+SC:wght@400;500;700'],
    ms: ['MS', 'ltr', ''],
    id: ['ID', 'ltr', ''],
    tr: ['TR', 'ltr', ''],
    th: ['ไทย', 'ltr', 'Noto+Sans+Thai:wght@400;500;600;700']
  };
  var BASE = (document.currentScript && document.currentScript.src)
    ? document.currentScript.src.replace(/js\/i18n\.js(\?.*)?$/, 'i18n/')
    : 'assets/i18n/';

  var dicts = { en: {} };
  var loading = {};
  var ATTRS = ['placeholder', 'aria-label', 'title'];
  var SKIP = { SCRIPT: 1, STYLE: 1, svg: 1, SVG: 1, NOSCRIPT: 1 };
  var originals = new WeakMap();
  var attrOriginals = new WeakMap();
  var meta = document.querySelector('meta[name="description"]');
  var origTitle = document.title;
  var origDesc = meta ? meta.getAttribute('content') : '';
  var current = 'en';

  function norm(s) { return s.replace(/\s+/g, ' ').trim(); }
  function lookup(text, lang) {
    if (lang === 'en') return null;
    var dict = dicts[lang] || {};
    var key = norm(text);
    return Object.prototype.hasOwnProperty.call(dict, key) ? dict[key] : null;
  }

  function load(lang) {
    if (dicts[lang]) return Promise.resolve(dicts[lang]);
    if (!loading[lang]) {
      loading[lang] = fetch(BASE + lang + '.json')
        .then(function (r) { if (!r.ok) throw new Error(r.status); return r.json(); })
        .then(function (d) { dicts[lang] = d; return d; })
        .catch(function () { delete loading[lang]; return null; });
    }
    return loading[lang];
  }

  function loadFont(lang) {
    var family = LANGS[lang] && LANGS[lang][2];
    if (!family || document.getElementById('font-' + lang)) return;
    var link = document.createElement('link');
    link.id = 'font-' + lang;
    link.rel = 'stylesheet';
    link.href = 'https://fonts.googleapis.com/css2?family=' + family + '&display=swap';
    document.head.appendChild(link);
  }

  function translateNode(root, lang) {
    var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT, {
      acceptNode: function (n) {
        if (n.nodeType === 1) return SKIP[n.nodeName] || n.hasAttribute('data-no-i18n') ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_SKIP;
        return /\S/.test(n.nodeValue) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP;
      }
    });
    var node;
    while ((node = walker.nextNode())) {
      if (!originals.has(node)) originals.set(node, node.nodeValue);
      var src = originals.get(node);
      var t = lookup(src, lang);
      if (t === null) { node.nodeValue = src; continue; }
      var lead = src.match(/^\s*/)[0], trail = src.match(/\s*$/)[0];
      node.nodeValue = lead + t + trail;
    }
    root.querySelectorAll('[' + ATTRS.join('],[') + ']').forEach(function (el) {
      var saved = attrOriginals.get(el) || {};
      ATTRS.forEach(function (a) {
        if (!el.hasAttribute(a)) return;
        if (!(a in saved)) saved[a] = el.getAttribute(a);
        var t = lookup(saved[a], lang);
        el.setAttribute(a, t === null ? saved[a] : t);
      });
      attrOriginals.set(el, saved);
    });
  }

  function render(lang) {
    current = lang;
    var root = document.documentElement;
    root.lang = lang;
    root.dir = LANGS[lang][1];
    translateNode(document.body, lang);
    document.title = lookup(origTitle, lang) || origTitle;
    if (meta) meta.setAttribute('content', lookup(origDesc, lang) || origDesc);
    try { localStorage.setItem('ts-lang', lang); } catch (e) { /* storage unavailable */ }
    document.dispatchEvent(new CustomEvent('ts:langchange', { detail: { lang: lang, label: LANGS[lang][0] } }));
  }

  function apply(lang) {
    if (!LANGS[lang]) lang = 'en';
    if (lang === 'en') { render('en'); return Promise.resolve(); }
    loadFont(lang);
    return load(lang).then(function (d) { render(d ? lang : 'en'); });
  }

  // Translate a single string from scripts (falls back to the English text)
  function t(text) { return lookup(text, current) || text; }

  var saved = 'en';
  try { saved = localStorage.getItem('ts-lang') || 'en'; } catch (e) { /* storage unavailable */ }

  window.tsI18n = { apply: apply, t: t, langs: LANGS, get lang() { return current; } };
  if (saved !== 'en' && LANGS[saved]) apply(saved);
})();
